function Edit-Text($file,$old,$new) { $p=Join-Path $PWD $file; $t=[IO.File]::ReadAllText($p); if(!$t.Contains($old)){Write-Output "NOT FOUND $file $old"}; [IO.File]::WriteAllText($p,$t.Replace($old,$new)) }
